fun tour(stops: Int, visit: (Int) -> Unit) {
    println("Welcome")
    repeat(stops) { visit(it + 1) }
    println("Goodbye")
}

fun main() {
    twice { println("hello") }
    tour(2) { println("Stop " + it) }
}

