fun times(count: Int, action: () -> Unit) {
    repeat(count) { action() }
    println("finished")
}

fun main() {
    times(0) { println("work") }
    times(2) { println("work") }
}

fun withTotal(a: Int, b: Int, show: (Int) -> Unit) {
    show(a + b)
}

fun main() {
    withTotal(3, 4) { println("Total: " + it) }
    withTotal(10, 5) { total -> println("Sum is $total") }
}
